import { useContext, useEffect, useState } from 'react';
import { Box, Grid, Typography } from '@mui/material';
import CustomAppBar from '../../components/shared-components/AppBar/AppBar';
import { SettingsContext } from '../../context/SettingsContext';
import Footer from '../../components/shared-components/Footer';
import WeatherWidget from '../../components/dashboard-components/WeatherWidget';
import ServerInfoWidget from '../../components/dashboard-components/ServerInfoWidget';
import ServerInfoLineChart from '../../components/dashboard-components/ServerInfoLineChart';
import DashboardService from '../../services/DashboardService';
import { useUser } from '../../context/UserContext';

const Dashboard = () => {
  const { language, themeMode} = useContext(SettingsContext);
  const { userState } = useUser();
  const [todayData, setTodayData] = useState(null);
  const [yesterdayData, setYesterdayData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refreshingNow, setRefreshingNow] = useState(false);
  const [chartData, setChartData] = useState([]);

  // 处理API返回的数据格式
  const processLogData = (data) => {
    if (!data) return null;
    
    return {
      cpuUsage: data.cpuUsage || 0,
      memoryUsage: data.memoryUsage || 0,
      memoryFree: data.memoryFree || 0,
      memoryAvailable: data.memoryAvailable || 0,
      diskUsage: data.diskUsage || 0,
      diskFree: data.diskFree || 0,
      apiCount: data.apiCount || 0,
      anonymousCount: data.anonymousCount || 0,
      blogCount: data.blogCount || 0,
      chatbotCount: data.chatbotCount || 0,
      myIpCount: data.myIPCount || 0,
      reportDate: data.reportDate || null
    };
  };

  // 获取AET时区的当前时间
  const getAETTime = () => {
    try {
      // 使用 Australia/Sydney 时区，与后端 CommonUtils.GetAETTime() 保持一致
      const now = new Date();
      const sydneyTime = new Date(now.toLocaleString("en-US", {timeZone: "Australia/Sydney"}));
      return sydneyTime;
    } catch (error) {
      console.error('Failed to get AET time:', error);
      // 如果时区转换失败，回退到 UTC+10
      const now = new Date();
      const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
      const aetTime = new Date(utc + (10 * 3600000));
      return aetTime;
    }
  };

  // 获取正确的日期
  const getCorrectDates = () => {
    const aetTime = getAETTime();
    const aetHour = aetTime.getHours();
    
    // 如果AET时间超过晚上10点，yesterday应该是今天的日期
    if (aetHour >= 22) {
      const today = aetTime.toISOString().split('T')[0];
      return {
        today: today,
        yesterday: today // 在晚上10点后，yesterday实际上是今天的日期
      };
    } else {
      // 正常情况：yesterday是昨天
      const yesterday = new Date(aetTime);
      yesterday.setDate(yesterday.getDate() - 1);
      const today = aetTime.toISOString().split('T')[0];
      return {
        today: today,
        yesterday: yesterday.toISOString().split('T')[0]
      };
    }
  };

  // 重新获取now数据
  const refreshNowData = async () => {
    if (!userState.access) return;
    
    try {
      setRefreshingNow(true);
      const response = await DashboardService.getLogNow(userState.access);
      setTodayData(processLogData(response));
    } catch (error) {
      console.error('Failed to refresh now data:', error);
    } finally {
      setRefreshingNow(false);
    }
  };

  useEffect(() => {
    const fetchData = async () => {
      if (!userState.access) {
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        
        const { today, yesterday } = getCorrectDates();
        
        // 并行获取今天和昨天的数据
        const [todayResponse, yesterdayResponse] = await Promise.all([
          DashboardService.getLogNow(userState.access),
          DashboardService.getLogByDate(yesterday, userState.access)
        ]);

        setTodayData(processLogData(todayResponse));
        setYesterdayData(processLogData(yesterdayResponse));

        // 获取近8天的日志，AET 为基准，endDate 用 AET+1 天，随后截取近7天
        const now = new Date();
        const sydneyTime = new Date(now.toLocaleString('en-US', { timeZone: 'Australia/Sydney' }));
        const endDate = new Date(sydneyTime);
        endDate.setDate(endDate.getDate() + 1);
        const startDate = new Date(sydneyTime);
        startDate.setDate(startDate.getDate() - 8);

        const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

        const params = {
          startDate: fmt(startDate),
          endDate: fmt(endDate),
          fields: 'reportDate,memoryUsage,memoryAvailable,apiCount,anonymousCount,chatbotCount',
          sortBy: 'reportdate',
          sortOrder: 'asc'
        };

        const logs = await DashboardService.getLogsWithFilter(params, userState.access);
        const list = logs?.data || [];

        // 规范化数据：取最后7天；x 轴为 MM-DD
        const normalized = list
          .map((x) => ({
            date: x.reportDate ? new Date(x.reportDate).toISOString().slice(5, 10) : '',
            memoryUsage: x.memoryUsage ?? 0,
            memoryAvailable: x.memoryAvailable ?? 0,
            apiCount: x.apiCount ?? 0,
            anonymousCount: x.anonymousCount ?? 0,
            chatbotCount: x.chatbotCount ?? 0,
          }))
          .slice(-7);

        setChartData(normalized);
      } catch (error) {
        console.error('Failed to fetch dashboard data:', error);
        // 如果API调用失败，使用默认数据
        setTodayData({
          cpuUsage: 0,
          memoryUsage: 0,
          memoryFree: 0,
          memoryAvailable: 0,
          diskUsage: 0,
          diskFree: 0,
          apiCount: 0,
          anonymousCount: 0,
          blogCount: 0,
          chatbotCount: 0,
          myIpCount: 0,
          reportDate: null
        });
        setYesterdayData({
          cpuUsage: 0,
          memoryUsage: 0,
          memoryFree: 0,
          memoryAvailable: 0,
          diskUsage: 0,
          diskFree: 0,
          apiCount: 0,
          anonymousCount: 0,
          blogCount: 0,
          chatbotCount: 0,
          myIpCount: 0,
          reportDate: null
        });
        setChartData([]);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [userState.access]);

  return (
    <Box
      sx={{
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      <CustomAppBar />
      
      {/* 主要内容区域 */}
      <Box
        sx={{
          flex: 1,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          mt: 12, // 给 AppBar 留出空间
          px: 2,
        }}
      >
        {/* Server Info Widgets */}
        <Box sx={{ mb: 4 }}>
          <Grid 
            container 
            spacing={{ xs: 2, md: 4 }} 
            justifyContent="center"
            direction={{ xs: 'column', md: 'row' }}
            alignItems="center"
          >
            <Grid item>
              <ServerInfoWidget 
                title="Now" 
                data={todayData}
                loading={loading || refreshingNow}
                onRefresh={refreshNowData}
                sx={{ 
                  boxShadow: 3
                }}
              />
            </Grid>
            <Grid item>
              <ServerInfoWidget 
                title="Yesterday" 
                data={yesterdayData}
                loading={loading}
                sx={{ 
                  boxShadow: 3
                }}
              />
            </Grid>
          </Grid>
        </Box>

        {/* 近7天折线图 - Mobile: 1x4, Desktop: 2x2 */}
        <Box sx={{ width: '100%', maxWidth: "1100px" }}>
          <Grid container spacing={2} columns={{ xs: 1, md: 2 }}>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="Memory Usage"
                data={chartData.map(d => ({
                  ...d,
                  memoryPercent: (d.memoryUsage + d.memoryAvailable) > 0
                    ? Math.round((d.memoryUsage / (d.memoryUsage + d.memoryAvailable)) * 100)
                    : 0
                }))}
                dataKey="memoryPercent"
                color="#ef5350"
                yAxisTickFormatter={(v) => `${v}%`}
                tooltipFormatter={(value) => [`${value}%`, 'Memory Usage']}
                loading={loading}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="Chatbot Calls"
                data={chartData}
                dataKey="chatbotCount"
                color="#8884d8"
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'Chatbot Calls']}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="API Calls"
                data={chartData}
                dataKey="apiCount"
                color="#82ca9d"
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'API Calls']}
              />
            </Grid>
            <Grid item xs={1} md={1}>
              <ServerInfoLineChart
                title="Anonymous Calls"
                data={chartData}
                dataKey="anonymousCount"
                color="#ff7300"
                loading={loading}
                tooltipFormatter={(value) => [String(value), 'Anonymous Calls']}
              />
            </Grid>
          </Grid>
        </Box>

        {/* <Box sx={{ mt: 8 }}>
          <WeatherWidget sx={{ width: "400px", height: "400px" }}/>
        </Box> */}
      </Box>

      {/* 下部 Footer */}
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          backgroundColor: 'background.default',
          borderTop: (theme) => ({
            xs: 'none',
            md: `1px solid ${theme.palette.divider}`,
          }),
          maxWidth: (theme) => theme.breakpoints.values.lg, 
          width: '100%', 
          mx: 'auto',
        }}
      >
        <Footer />
      </Box>

      
    </Box>
  );
};

export default Dashboard;
