import api from './api';

const DashboardService = {
    getLogNow: async (accessToken) => {
        const response = await api.get('/log/now', {
            headers: {
                Authorization: `Bearer ${accessToken}`,
            },
        });
        return response.data;
    },

    getLogByDate: async (reportDate, accessToken) => {
        const formData = new FormData();
        formData.append('reportDate', reportDate);

        const response = await api.post('/log/by-date', formData, {
            headers: {
                'Content-Type': 'multipart/form-data',
                Authorization: `Bearer ${accessToken}`,
            },
        });
        return response.data;
    },

    getLogsWithFilter: async (params = {}, accessToken) => {
        const queryParams = new URLSearchParams();
        
        // 添加查询参数
        if (params.startDate) {
            queryParams.append('startDate', params.startDate);
        }
        if (params.endDate) {
            queryParams.append('endDate', params.endDate);
        }
        if (params.fields) {
            queryParams.append('fields', params.fields);
        }
        if (params.limit) {
            queryParams.append('limit', params.limit);
        }
        if (params.sortBy) {
            queryParams.append('sortBy', params.sortBy);
        }
        if (params.sortOrder) {
            queryParams.append('sortOrder', params.sortOrder);
        }

        const url = `/log/filter${queryParams.toString() ? '?' + queryParams.toString() : ''}`;
        
        const response = await api.get(url, {
            headers: {
                Authorization: `Bearer ${accessToken}`,
            },
        });
        return response.data;
    },
};

export default DashboardService;